package org.usbworkbench;
import java.io.*;import java.nio.*;import java.util.*;
public final class FileProtocolTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}interface A{void run()throws Exception;}static void fails(String code,A a)throws Exception{try{a.run();throw new AssertionError("expected "+code);}catch(IOException e){check(e.getMessage().startsWith(code),e.toString());}}
 static final class MemoryFile implements WimFiles.RandomFile {byte[] data=new byte[0];boolean corrupt;public long size(){return data.length;}public int read(long offset,byte[] b){int n=(int)Math.min(b.length,data.length-offset);System.arraycopy(data,(int)offset,b,0,n);if(corrupt&&n>0)b[0]^=1;return n;}public void write(long offset,byte[] b){if(offset+b.length>data.length)data=Arrays.copyOf(data,(int)offset+b.length);System.arraycopy(b,0,data,(int)offset,b.length);}public void truncate(long n){data=Arrays.copyOf(data,(int)n);}public void sync(){}public void close(){}}
 static byte[] request(int op,int id,int count,long offset,byte[] payload)throws IOException {ByteArrayOutputStream out=new ByteArrayOutputStream();ByteBuffer b=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{'U','W','F','1'}).putInt(op).putInt(id).putInt(count).putLong(offset);out.write(b.array());if(payload!=null)out.write(payload);return out.toByteArray();}
 static byte[] serve(WimFiles files,byte[] request)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();FileProtocol.serve(new ByteArrayInputStream(request),out,files,(a,b)->{});return out.toByteArray();}
 public static void main(String[] args)throws Exception {
  for(String path:new String[]{"/usbwb/../evil","/usbwb/install1.swm","/usbwb/install257.swm","/usbwb/install02.swm","/tmp/source.wim","/usbwb/install2.swm/evil"})fails("FILE_PATH",()->FileProtocol.name(path.getBytes("US-ASCII")));
  check(FileProtocol.name("/usbwb/install256.swm".getBytes("US-ASCII")).equals("install256.swm"),"last bounded part");
  MemoryFile output=new MemoryFile();OpticalImage.Source source=new OpticalImage.Source(){public long size(){return 8;}public void read(long at,byte[] b,int off,int n){Arrays.fill(b,off,off+n,(byte)42);}public void close(){}};
  try(WimFiles files=new WimFiles(source,new WimFiles.Store(){public WimFiles.RandomFile create(String n){return output;}public void capacity(long n){}})){
   byte[] name="/usbwb/source.wim".getBytes("US-ASCII");byte[] reply=serve(files,request(1,0,name.length,0,name));ByteBuffer opened=ByteBuffer.wrap(reply).order(ByteOrder.LITTLE_ENDIAN);check(opened.getInt()==0,"open source status");int id=opened.getInt();check(opened.getLong()==8,"source size");reply=serve(files,request(2,id,20,6,null));check(ByteBuffer.wrap(reply).order(ByteOrder.LITTLE_ENDIAN).getInt(4)==2&&reply.length==18,"short read/EOF bounded to source size");reply=serve(files,request(3,id,1,0,new byte[1]));check(ByteBuffer.wrap(reply).order(ByteOrder.LITTLE_ENDIAN).getInt()==30,"read-only write is POSIX error reply");
   reply=serve(files,request(4,999,0,0,null));check(ByteBuffer.wrap(reply).order(ByteOrder.LITTLE_ENDIAN).getInt()==9,"unknown handle EBADF");
   fails("FILE_PROTOCOL",()->serve(files,request(2,id,FileProtocol.MAX_IO+1,0,null)));fails("FILE_BOUNDS",()->serve(files,request(2,id,1,-1,null)));fails("FILE_PROTOCOL",()->serve(files,request(99,id,0,0,null)));fails("FILE_PROTOCOL",()->serve(files,request(4,id,1,0,null)));fails("SOURCE_SHORT",()->serve(files,new byte[]{'U','W','F','1'}));
   FileProtocol.Handle part=files.open("install.swm",578);files.write(part.id,0,new byte[]{1,2,3});check(output.size()==3,"new output write");fails("FILE_BOUNDS",()->files.write(part.id,FileProtocol.MAX_FILE,new byte[1]));fails("FILE_BOUNDS",()->files.write(part.id,WimFiles.MAX_PART_BYTES,new byte[1]));check(output.size()==3,"oversize write does not mutate");output.corrupt=true;fails("VERIFY_FAILED",()->files.write(part.id,0,new byte[]{4}));output.corrupt=false;files.close(part.id);files.seal();try{files.open("install2.swm",578);throw new AssertionError("sealed create accepted");}catch(FileProtocol.FileError e){check(e.errno==30,"sealed verify mode refuses new output");}
  }
  System.out.println("PASS: "+checks+" file RPC paths, sizes, short reads, errors, source protection, readback and sealed outputs");
 }
}
